#!/bin/bash
set -eu
export PYTHONDONTWRITEBYTECODE=1
exec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PYREMOTE'
import base64,hashlib,json,os,subprocess,tarfile,time
from pathlib import Path
base=Path('/home/loosqk/robot-checks/position-return-20261011-r12/native-quality')
base.parent.mkdir(exist_ok=True)
base.mkdir()
boot=base/'boot';boot.mkdir();(boot/'incoming').mkdir()
payload={'quality_once_r12.py': {'base64': '', 'sha256': 'f05246d4d4405255b2877722f31a17baeca99e5a78fa37ee37ce9375b24940c2', 'bytes': 10217}, 'launch_quality_r12.sh': {'base64': '', 'sha256': 'd7fbd7efec9c7df1e29b57326f2eeebac975447d607fbeade819dcd5288e5611', 'bytes': 448}, 'host_source_final_r12.json': {'base64': '', 'sha256': '252ab813198e765cae05db2e8dc333417415a253e33b75c3ed3a31158e822d2f', 'bytes': 114885}, 'incoming/feetech_poke.rs': {'base64': '', 'sha256': 'd22e35c993d38522ecd822c7482a0d2386e4d8b77c788b95812d76c4ecfed92e', 'bytes': 23499}, 'incoming/bus.rs': {'base64': '', 'sha256': '5aeb0c4c94bb4258986d51ade80b6f8bb2960c1ad3b67b648855c7576d567205', 'bytes': 53667}, 'incoming/bus_raw_read_tests.rs': {'base64': '', 'sha256': 'cd548199e3693714efea8cdfb3a6dc34b3340cb7c815a3799f81bd5ac34dc144', 'bytes': 18752}, 'incoming/diagnostic.rs': {'base64': '', 'sha256': 'f1d837be8029490328010de20a833881a7b26754dd04ffbbd8097eb5256e6520', 'bytes': 15431}, 'incoming/registers.rs': {'base64': '', 'sha256': 'cd803f78c3d9177b9b1dbffd8a65a81c0f61338b8e5461bb74b1a2df9cacf205', 'bytes': 17594}}
for name,value in payload.items():
 raw=base64.b64decode(value['base64'],validate=True)
 assert len(raw)==value['bytes'] and hashlib.sha256(raw).hexdigest()==value['sha256']
 with (boot/name).open('xb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
rows=[]
def command(name,argv,accepted):
 started=time.time_ns();child=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE);stdout,stderr=child.communicate();code=child.wait()
 row={'name':name,'argv':argv,'pid':child.pid,'started_ns':started,'finished_ns':time.time_ns(),'exit_code':code,'wait_returncode':code,'reaped':True,'stdout':stdout.decode(),'stderr':stderr.decode(),'signals_sent':[]};rows.append(row)
 assert code in accepted,row
 return code,stdout,stderr
_,raw,_=command('single-tmux-software-start',['tmux','new-session','-d','-s','position-native-quality-20261011-r12','-P','-F','#{session_name} #{window_id} #{pane_id} #{pane_pid}','bash '+str(boot/'launch_quality_r12.sh')],(0,))
session,window,pane,pid=raw.decode().split();assert session=='position-native-quality-20261011-r12' and pid.isdigit()
with (boot/'start.json').open('x') as stream:json.dump(rows[-1],stream,ensure_ascii=False,indent=2);stream.write('\n')
print(json.dumps({'phase':'ACTUAL_SINGLE_NATIVE_QUALITY_START','runtime_pid':int(pid),'pane':pane,'tmux_launch':rows[-1]},ensure_ascii=False),flush=True)
observer='#!/bin/bash\n# 本轮R12单次nightly更新观察；无UART/GO/服务动作。\n# SSH 等待同一 pane 的退出通知，通知后仍只读核验真实终态。\nset -euC\numask 077\nexport PATH=/home/loosqk/.cargo/bin:/home/loosqk/.local/bin:$PATH\nbase=/home/loosqk/robot-checks/position-return-20261011-r12/native-quality\nrecord="$base/observer-event"\nmkdir "$record"\nprintf \'%s\\n\' \'__ACTUAL_PANE_PID_WINDOW__\' > "$record/pane.txt"\nread -r pane driver_pid window < "$record/pane.txt"\ncase "$pane" in %[0-9]*) ;; *) exit 2;; esac\ncase "$driver_pid" in \'\'|*[!0-9]*) exit 2;; esac\n# 同一服务器的 pane_id 不复用；同一记录目录的 observer PID 文件不覆盖。\n# 每个观察者有自己的 indexed hook/channel，续接不覆盖旧 waiter。\nobserver=$$\nchannel="quality.pane.${pane#%}.driver.$driver_pid.observer.$observer"\nhook="pane-died[$observer]"\nprintf \'%s\\n\' "$channel" > "$record/observer-$observer.channel"\nbefore_hooks=$(tmux show-hooks -p -t "$pane")\nprintf \'%s\\n\' "$before_hooks" > "$record/observer-$observer.hooks-before"\nwhile read -r hook_name hook_command; do\n  if [ "$hook_name" = "$hook" ]; then exit 2; fi\ndone <<< "$before_hooks"\ncleanup_hook() {\n  tmux set-hook -pu -t "$pane" "$hook"\n}\ntrap cleanup_hook EXIT\ntmux set-hook -p -t "$pane" "$hook" "wait-for -S $channel"\ntmux show-hooks -p -t "$pane" > "$record/observer-$observer.hooks-after"\nobserve() {\n  state=$(tmux display-message -p -t "$pane" \'#{pane_id} #{pane_pid} #{pane_dead} #{pane_dead_status}\')\n  printf \'%s\\n\' "$state" >> "$record/observer-$observer.log"\n  read -r observed_pane observed_pid dead status <<< "$state"\n  test "$observed_pane" = "$pane"\n  test "$observed_pid" = "$driver_pid"\n}\n# 挂钩后查询：先退出的 pane 直接核验；查询到存活后的退出由 channel 留存通知。\nobserve\nif [ "$dead" = 0 ]; then\n  tmux wait-for "$channel"\n  observe\nfi\n# 提前或错误通知不能变成 PASS，也不再次等待/启动。\nif [ "$dead" != 1 ]; then exit 2; fi\nprintf \'%s\\n\' "$state" > "$record/observer-$observer.terminal"\n    case "$status" in 0|1) ;; *) exit 2;; esac\n    /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - "$base/quality/result.json" "$driver_pid" "$status" <<\'PYRESULT\'\nimport hashlib,json,sys\nfrom pathlib import Path\np=Path(sys.argv[1]);raw=p.read_bytes();j=json.loads(raw)\nassert j[\'schema\']==\'R12_MINIMAL_NATIVE_QUALITY_V1\'\nassert int(sys.argv[3])==(0 if j[\'status\']==\'PASS\' else 1)\nprint(json.dumps({\'status\':\'R12_MINIMAL_QUALITY_REAL_TERMINAL\',\'pane_pid\':int(sys.argv[2]),\'pane_exit\':int(sys.argv[3]),\'result_status\':j[\'status\'],\'result_sha256\':hashlib.sha256(raw).hexdigest(),\'result_bytes\':len(raw),\'source_before_after\':j.get(\'source_before_after\'),\'compiler\':j.get(\'compiler\'),\'unique_tests\':j.get(\'unique_tests\'),\'cli_receipts\':len(j.get(\'cli_receipts\',[])),\'receipts\':len(j[\'receipts\']),\'error\':j.get(\'error\')},ensure_ascii=False),flush=True)\nPYRESULT\nexit "$status"\n'
assert observer.count('__ACTUAL_PANE_PID_WINDOW__')==1
observer=observer.replace('__ACTUAL_PANE_PID_WINDOW__',pane+' '+pid+' '+window)
with (boot/'observe_quality_r12.sh').open('x') as stream:stream.write(observer)
code,stdout,stderr=command('same-pane-observer',['bash',str(boot/'observe_quality_r12.sh')],(0,1,2))
for suffix,raw in [('stdout',stdout),('stderr',stderr)]:
 with (boot/('observer.'+suffix)).open('xb') as stream:stream.write(raw)
print(stdout.decode(),end='',flush=True)
if stderr:print(json.dumps({'phase':'OBSERVER_STDERR','stderr':stderr.decode()},ensure_ascii=False),flush=True)
_,state,_=command('terminal-identity',['tmux','display-message','-p','-t',pane,'#{session_name}|#{window_id}|#{pane_id}|#{pane_dead}|#{pane_dead_status}|#{pane_pid}'],(0,))
parts=state.decode().strip().split('|');assert parts[:3]==[session,window,pane] and parts[3]=='1' and parts[4] in ['0','1'] and parts[5]==pid
command('reclaim-natural-dead-owned-pane',['tmux','kill-pane','-t',pane],(0,))
with (boot/'same-ssh.json').open('x') as stream:json.dump(rows,stream,ensure_ascii=False,indent=2);stream.write('\n')
paths=sorted(x for directory in (base/'quality',base/'observer-event',boot) for x in directory.rglob('*') if x.is_file() and 'incoming' not in x.parts)
frozen=base.parent/'readback-tool-r12/feetech_poke'
if frozen.exists():paths.append(frozen)
assert all(not x.is_symlink() for x in paths)
archive=base/'native-originals.tar.gz'
with tarfile.open(archive,'x:gz') as stream:
 for path in paths:stream.add(path,arcname=str(path.relative_to(base)) if path.is_relative_to(base) else 'frozen/feetech_poke',recursive=False)
raw=archive.read_bytes();result=base/'quality/result.json'
print(json.dumps({'phase':'NATIVE_QUALITY_ARCHIVE_READY','sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'files':len(paths),'source_bytes':sum(x.stat().st_size for x in paths),'base64':base64.b64encode(raw).decode(),'runtime_pid':int(pid),'pane_exit':int(parts[4]),'result_sha256':hashlib.sha256(result.read_bytes()).hexdigest(),'result_bytes':result.stat().st_size},ensure_ascii=False),flush=True)
raise SystemExit(code)
